import { NextResponse, type NextRequest } from 'next/server';
import { API_URL } from '@/lib/config';
import { getAccessToken } from '@/lib/session';

// Receipts and loan statements are PDFs generated by the backend. The browser can't attach the
// httpOnly access-token cookie to a request for the backend directly, so the download is proxied
// here: the token is read server-side, the backend enforces the caller's permissions and branch
// scope (and audits the download), and the PDF is streamed straight back.
const PATHS: Record<string, (id: string) => string> = {
  receipt: (id) => `/documents/receipts/${id}/pdf`,
  statement: (id) => `/documents/loans/${id}/statement/pdf`,
  'auction-notice': (id) => `/documents/auctions/${id}/notice/pdf`,
};
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export async function GET(req: NextRequest, { params }: { params: Promise<{ kind: string; id: string }> }) {
  const { kind, id } = await params;
  const path = PATHS[kind];
  if (!path || !UUID.test(id)) return new NextResponse('Document not found.', { status: 404 });

  const token = await getAccessToken();
  if (!token) return NextResponse.redirect(new URL('/login', req.url));

  const res = await fetch(`${API_URL}${path(id)}`, { headers: { Authorization: `Bearer ${token}` }, cache: 'no-store' });
  if (!res.ok) {
    const status = [401, 403, 404, 409].includes(res.status) ? res.status : 502;
    const message =
      status === 403
        ? 'You do not have permission to view this document.'
        : status === 404
          ? 'Document not found.'
          : status === 409
            ? 'This document is not available right now (for example, the auction it belongs to is no longer open).'
            : 'The document could not be generated. Please try again.';
    return new NextResponse(message, { status });
  }
  return new NextResponse(res.body, {
    headers: {
      'Content-Type': 'application/pdf',
      'Content-Disposition': res.headers.get('content-disposition') ?? 'inline; filename="document.pdf"',
      'Cache-Control': 'no-store',
      'X-Content-Type-Options': 'nosniff',
    },
  });
}
